#include <bits/stdc++.h>
using namespace std;int n;using U=uint64_t;vector<vector<pair<int,int>>> ms;vector<U> seqs;unordered_map<U,bool> memo;int forbid[12];
void gen(vector<int> v, vector<pair<int,int>> m){if(v.empty()){sort(m.begin(),m.end());ms.push_back(m);return;}int a=v[0];for(int j=1;j<(int)v.size();j++){vector<int>w;for(int x:v)if(x!=a&&x!=v[j])w.push_back(x);auto z=m;z.push_back({a,v[j]});gen(w,z);}}
void sq(int i,int last,U key,int sum){if(i==n){if(sum%2==0)seqs.push_back(key);return;}for(int d=last;d>=1;d--)sq(i+1,d,key|((U)(d-1)<<(4*i)),sum+d);}
bool ok(U key){if(!key)return true;auto it=memo.find(key);if(it!=memo.end())return it->second;int ds[12],a=0;for(int i=0;i<n;i++){ds[i]=(key>>(4*i))&15;if(ds[i]>ds[a])a=i;}int cand=0;for(int i=0;i<n;i++)if(i!=a&&i!=forbid[a]&&ds[i])cand|=1<<i;int d=ds[a];if(__builtin_popcount((unsigned)cand)<d)return memo[key]=false;U rest=key&~(15ULL<<(4*a));for(int sub=cand;sub;sub=(sub-1)&cand){if(__builtin_popcount((unsigned)sub)!=d)continue;U q=rest;for(int i=0;i<n;i++)if(sub>>i&1)q-=1ULL<<(4*i);if(ok(q))return memo[key]=true;}return memo[key]=false;}
int main(int argc,char**argv){n=atoi(argv[1]);vector<int>v(n);iota(v.begin(),v.end(),0);gen(v,{});sq(0,n-1,0,0);int z=ms.size(),w=(seqs.size()+63)/64;vector<vector<U>> real(z,vector<U>(w));map<vector<pair<int,int>>,int> ix;for(int j=0;j<z;j++)ix[ms[j]]=j;vector<bitset<1024>> reach(z);for(int j=0;j<z;j++){reach[j].set(j);auto m=ms[j];for(int e=0;e<n/2;e++)for(int f=e+1;f<n/2;f++){vector<int>v={m[e].first,m[e].second,m[f].first,m[f].second};sort(v.begin(),v.end());int a=v[0],b=v[1],c=v[2],d=v[3];vector<vector<pair<int,int>>>p={{{a,b},{c,d}},{{a,c},{b,d}},{{a,d},{b,c}}};vector<pair<int,int>>orig={m[e],m[f]};sort(orig.begin(),orig.end());int k=find(p.begin(),p.end(),orig)-p.begin();for(int h=k+1;h<3;h++){vector<pair<int,int>>q;for(int r=0;r<n/2;r++)if(r!=e&&r!=f)q.push_back(m[r]);q.insert(q.end(),p[h].begin(),p[h].end());sort(q.begin(),q.end());reach[j].set(ix.at(q));}}}
for(int k=0;k<z;k++)for(int j=0;j<z;j++)if(reach[j][k])reach[j]|=reach[k];
for(int j=0;j<z;j++){memo.clear();for(auto [a,b]:ms[j])forbid[a]=b,forbid[b]=a;for(int s=0;s<(int)seqs.size();s++)if(ok(seqs[s]))real[j][s/64]|=1ULL<<(s%64);cerr<<"completed matching "<<j+1<<"/"<<z<<" memo "<<memo.size()<<endl;}
int comparable=0,viol=0;for(int j=0;j<z;j++)for(int i=0;i<z;i++){bool subset=true;for(int k=0;k<w;k++)if(real[j][k]&~real[i][k]){subset=false;break;}if(subset){comparable++;if(!reach[j][i]){viol++;cout<<"VIOL "<<i<<" "<<j<<endl;}}}cout<<"n "<<n<<" matchings "<<z<<" sorted_even_positive_sequences "<<seqs.size()<<" comparable "<<comparable<<" violations "<<viol<<endl;}
